import "encoding/json"

// UsersRecordsTest checks UsersRecords.Normalized against what the
// JavaScript UsersRecords.normalize answered for the same users.
// @Test(UsersTestSetup)
type UsersRecordsTest struct {
	behaviors *BehaviorContext
}

func (test *UsersRecordsTest) users() []map[string]any {
	var users []map[string]any
	_ = json.Unmarshal([]byte(`[{"aliases":["ada@example.com","A.L@example.com","x","a.l@example.com"],"calendarVisibility":"busy","categoryCatalog":{"example.com":{"Projects/A":"Folder","a-b":"label","a.b":"label","a_b":"folder","bad//x":"label","tags":"label","z":"neither"}},"categoryMappings":{"example.com":{"drafts":"system/drafts","inbox":"Inbox","sent":"inbox"}},"composerFont":"bogus","domains":["Example.com","bad","example.com","Other.org."],"email":"  Ada@Example.COM ","githubProfileEnrichment":"yes","grammarCheckDisabledRules":["A_B","A_B","C"],"grammarCheckEnabled":true,"grammarCheckLanguage":"en-GB","id":"u1","interfaceFont":"serif","interfaceLocale":"de","keyboardShortcutOverrides":{"core:compose":"Shift + C","core:refresh":"c","core:search":"","unknown":"x"},"mailPreferences":{"autoCcBySender":{"ada@example.com":["c@x.com","C@x.com"],"zed@x.com":["d@x.com"]},"defaultFrom":"A.L@example.com","findInMailDisabledDomains":["other.org","nope.com"],"interfaceScale":1.1,"markAsReadDelay":3,"swipeEnabled":false,"workspaceLayout":"list"},"mailboxNames":{"example.com":" Work ","gone.com":"x","other.org":"a\u0001b"},"mcp":{"accessLevel":"read-write","allowedDomains":["other.org","zzz.com"],"enabled":true,"excludedFolders":{"example.com":["a"],"other.org":["Spam","../x","spam"]}},"name":"Ada","newMailNotificationActions":false,"newMailNotificationDomains":["other.org","nope.com","other.org"],"newMailNotificationExternalAccounts":["ext_abcdefghijklmnopqrstuv","bad"],"newMailNotificationPrivacy":"sender","notificationSounds":{"new-mail":"bell","send":"nope"},"phones":["1"],"remoteImagePolicy":"allow","themePreferences":{"activeTheme":"dark","lightTheme":"dark"},"trustedImageSenders":["B@x.com","b@x.com","nope"],"unreadBadgeDomain":"OTHER.org","unreadBadgeScope":"domain"},{"domains":[],"email":"not-an-email","id":"u2"}]`), &users)
	return users
}

func (test *UsersRecordsTest) normalized(index int) string {
	return StoredRecords{}.JsonText(UsersRecords{}.Normalized(test.users()[index]))
}

